parameters.checklist:
[
  {
    "id": "write-produced-a-change",
    "assert": "this state changed something under the declared source or test paths",
    "cmd": "git diff --name-only ${base_ref} -- ${src_path} ${test_path} | grep -q . || git ls-files --others --exclude-standard -- ${src_path} ${test_path} | grep -q .",
    "origin": "pe-profile:tdd_feature@1.0.0"
  }
]

[
  {
    "id": "tests_written",
    "assert": "tests_written",
    "cmd": "git diff --name-only ${base_ref} -- ${test_path} | grep -q . || git ls-files --others --exclude-standard -- ${test_path} | grep -q .",
    "origin": "pe-profile:tdd_feature@1.0.0"
  },
  {
    "id": "implementation_done",
    "assert": "implementation_done",
    "cmd": "git diff --name-only ${base_ref} -- ${src_path} | grep -q . || git ls-files --others --exclude-standard -- ${src_path} | grep -q .",
    "origin": "pe-profile:tdd_feature@1.0.0"
  },
  {
    "id": "suite_green",
    "assert": "suite_green",
    "cmd": "${test_cmd}",
    "origin": "pe-profile:tdd_feature@1.0.0"
  }
]

[
  {
    "id": "review-is-substantive",
    "assert": "the review artifact carries at least 50 words",
    "cmd": "test \"$(wc -w < ${review_artifact})\" -ge 50",
    "origin": "pe-profile:tdd_feature@1.0.0"
  },
  {
    "id": "review-engages-with-the-diff",
    "context": [
      "${review_artifact}"
    ],
    "judge": "Does this review describe the specific change in the diff — the functions, behaviours and edge cases it introduces — and raise concrete concerns about it? FAIL if it approves or rejects without naming specific items from the diff, if it makes a claim the diff does not support, if it is generic enough to apply to any artifact of this kind, or if it leaves part of the diff unjudged.",
    "diff": true,
    "blocking": true,
    "origin": "pe-profile:tdd_feature@1.0.0"
  }
]
